#include "../core/internal.h"
#include "laststate/network_transport.h"
#include "laststate/envelope.h"
ls_result_t ls_http_transport_send(void *context,const uint8_t *data,size_t length){ls_http_transport_t *http=(ls_http_transport_t *)context;if(!http||!http->post||!http->endpoint||(!data&&length))return LS_EINVAL;uint16_t status=0;ls_result_t result=http->post(http->context,http->endpoint,"application/vnd.laststate.lep",data,length,&status);if(result!=LS_OK)return result;return status>=200u&&status<300u?LS_OK:(status==408u||status==429u||status>=500u?LS_EAGAIN:LS_EIO);}
size_t ls_http_transport_max_payload(void *context){ls_http_transport_t *http=(ls_http_transport_t *)context;return http&&http->maximum_payload?http->maximum_payload:LS_MAX_EVENT_SIZE;}
ls_result_t ls_mqtt_transport_send(void *context,const uint8_t *data,size_t length){ls_mqtt_transport_t *mqtt=(ls_mqtt_transport_t *)context;if(!mqtt||!mqtt->publish||!mqtt->topic||(!data&&length))return LS_EINVAL;return mqtt->publish(mqtt->context,mqtt->topic,data,length,mqtt->qos,false);}
size_t ls_mqtt_transport_max_payload(void *context){ls_mqtt_transport_t *mqtt=(ls_mqtt_transport_t *)context;return mqtt&&mqtt->maximum_payload?mqtt->maximum_payload:LS_MAX_EVENT_SIZE;}
ls_result_t ls_incident_beacon_encode(const uint8_t *envelope,size_t envelope_length,uint32_t device_hash,uint16_t battery_mv,int16_t temperature_c,uint8_t *output,size_t capacity,size_t *written){if(!envelope||!output||!written||capacity<32u)return LS_EINVAL;ls_envelope_info_t info;ls_result_t result=ls_envelope_validate(envelope,envelope_length,&info);if(result!=LS_OK)return result;ls_writer_t writer={output,capacity,0};(void)ls_writer_u32(&writer,0x4249534cu);(void)ls_writer_u8(&writer,1);(void)ls_writer_u8(&writer,info.type);(void)ls_writer_u8(&writer,info.architecture);(void)ls_writer_u8(&writer,info.flags);(void)ls_writer_u32(&writer,info.event_id);(void)ls_writer_u32(&writer,device_hash);(void)ls_writer_u32(&writer,ls_hash_string(ls_build_id()));(void)ls_writer_u16(&writer,battery_mv);(void)ls_writer_u16(&writer,(uint16_t)temperature_c);(void)ls_writer_u32(&writer,info.sequence);(void)ls_writer_u32(&writer,ls_crc32(output,writer.length));*written=writer.length;return LS_OK;}
